import{_ as e,c as t,o as r,ai as o}from"./chunks/framework.B63Sb1io.js";const c=JSON.parse('{"title":"计算机网络的功能","titleTemplate":"408计算机网络","description":"综述","frontmatter":{"title":"计算机网络的功能","titleTemplate":"408计算机网络","description":"综述","layout":"doc","navbar":true,"sidebar":true,"aside":true,"outline":"deep","lastUpdated":true,"prev":false,"next":false},"headers":[],"relativePath":"post/kaoyan/408/408_CN/01/408_CN_3.md","filePath":"post/kaoyan/408/408_CN/01/408_CN_3.md","lastUpdated":1756187359000}'),l={name:"post/kaoyan/408/408_CN/01/408_CN_3.md"};function i(n,a,s,d,p,_){return r(),t("div",null,a[0]||(a[0]=[o('<h1 id="计算机网络的功能" tabindex="-1">计算机网络的功能 <a class="header-anchor" href="#计算机网络的功能" aria-label="Permalink to &quot;计算机网络的功能&quot;">​</a></h1><br><p>计算机网络的功能很多，现今的很多应用都与网络有关。主要有以下五大功能。</p><h2 id="数据通信" tabindex="-1">数据通信 <a class="header-anchor" href="#数据通信" aria-label="Permalink to &quot;数据通信&quot;">​</a></h2><p>数据通信是计算机网络最基本和最重要的功能，用来实现联网计算机之间各种信息的传输。</p><blockquote><p>例如，文件传输、电子邮件等应用，离开了计算机网络就无法实现。</p></blockquote><h2 id="资源共享" tabindex="-1">资源共享 <a class="header-anchor" href="#资源共享" aria-label="Permalink to &quot;资源共享&quot;">​</a></h2><p>资源共享既可是软件共享、数据共享，又可是硬件共享。它使计算机网络中的资源互通有无、分工协作，从而极大地提高了硬件资源、软件资源和数据资源的利用率。</p><h2 id="分布式处理" tabindex="-1">分布式处理 <a class="header-anchor" href="#分布式处理" aria-label="Permalink to &quot;分布式处理&quot;">​</a></h2><p>当计算机网络中的某个计算机系统负荷过重时，可将其处理的某个复杂任务分配给网络中的其他计算机系统，从而利用空闲计算机资源来提高整个系统的利用率。</p><h2 id="提高可靠性" tabindex="-1">提高可靠性 <a class="header-anchor" href="#提高可靠性" aria-label="Permalink to &quot;提高可靠性&quot;">​</a></h2><p>计算机网络中的各台计算机可以通过网络互为替代机。</p><h2 id="负载均衡" tabindex="-1">负载均衡 <a class="header-anchor" href="#负载均衡" aria-label="Permalink to &quot;负载均衡&quot;">​</a></h2><p>将工作任务均衡地分配给计算机网络中的各台计算机。 除了以上几大主要功能，计算机网络还可实现电子化办公与服务、远程教育、娱乐等功能，满足了社会的需求，方便了人们的学习、工作和生活，具有巨大的经济效益。</p>',14)]))}const u=e(l,[["render",i]]);export{c as __pageData,u as default};
